# resolution.toml — entity-resolution weights and thresholds (ADR-030).
#
# Consumed by the scribe's daemon-side resolver (task_45). Shipped and
# validated by task_38 so the file exists, loads, and has sane starting
# values before the resolver lands. Installed to
# $FFS_DATA_DIR/config/resolution.toml; git-versioned and owner-edited
# like the predicate specs.
#
# Model: Fellegi-Sunter style. Each compared field contributes `agree`
# when the candidate and the proposal agree on it and `disagree` when
# they disagree (both in log-odds units; positive favors a match). The
# summed score is compared against two thresholds:
#
#   score >= auto_link     -> resolution: existing (link to the candidate)
#   score <  review_floor  -> resolution: new     (mint a fresh entity)
#   otherwise              -> resolution: ambiguous (route to the owner)
#
# The band between the thresholds is the clerical-review band. Start
# wide; narrow only when the golden corpus (task_36, task_45) justifies it.

[thresholds]
auto_link = 8.0
review_floor = 2.0

# Agreement on organization is strong evidence: two "Sara Chen" at the
# same company are almost certainly one person. A shared surname alone
# is weak: common names collide constantly, so its agree weight is small
# and its disagree weight is strongly negative (different surname, not
# the same person).

[weights.display_name]
agree = 6.0
disagree = -4.0

[weights.alias]
agree = 5.0
disagree = 0.0

[weights.organization]
agree = 4.0
disagree = -2.0

[weights.role]
agree = 1.5
disagree = -0.5

[weights.location]
agree = 1.0
disagree = -0.5

[weights.surname]
agree = 0.5
disagree = -6.0
EOF
cat > crates/ffs-core/src/resolution.rs <<'EOF'
//! Entity-resolution configuration (ADR-030): Fellegi-Sunter style
//! agreement weights per compared field plus the two thresholds that
//! split scores into `existing` / `ambiguous` / `new`.
//!
//! This module only loads and validates the file. The resolver that
//! consumes it is task_45 (daemon side). Shipped in
//! `starter/config/resolution.toml` and installed to
//! `$FFS_DATA_DIR/config/resolution.toml`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use thiserror::Error;

#[derive(Debug, Error)]
pub enum ResolutionConfigError {
    #[error("io error reading {path}: {source}")]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
    #[error("toml parse error in resolution config: {0}")]
    Toml(#[from] toml::de::Error),
    #[error("thresholds must satisfy review_floor < auto_link (got review_floor={review_floor}, auto_link={auto_link})")]
    ThresholdOrder { review_floor: f64, auto_link: f64 },
    #[error("resolution config declares no weights")]
    NoWeights,
}

/// Log-odds contribution of one compared field.
#[derive(Debug, Clone, Copy, PartialEq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct FieldWeight {
    pub agree: f64,
    pub disagree: f64,
}

#[derive(Debug, Clone, Copy, PartialEq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Thresholds {
    /// Scores at or above this link to the best candidate.
    pub auto_link: f64,
    /// Scores below this mint a new entity; between the two is review.
    pub review_floor: f64,
}

#[derive(Debug, Clone, PartialEq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ResolutionConfig {
    pub thresholds: Thresholds,
    /// Keyed by compared field name (`display_name`, `alias`, ...).
    pub weights: BTreeMap<String, FieldWeight>,
}

impl ResolutionConfig {
    pub fn from_toml_str(content: &str) -> Result<Self, ResolutionConfigError> {
        let cfg: ResolutionConfig = toml::from_str(content)?;
        cfg.validate()?;
        Ok(cfg)
    }

    pub fn load(path: &Path) -> Result<Self, ResolutionConfigError> {
        let content = std::fs::read_to_string(path).map_err(|e| ResolutionConfigError::Io {
            path: path.to_path_buf(),
            source: e,
        })?;
        Self::from_toml_str(&content)
    }

    fn validate(&self) -> Result<(), ResolutionConfigError> {
        if self.thresholds.review_floor >= self.thresholds.auto_link {
            return Err(ResolutionConfigError::ThresholdOrder {
                review_floor: self.thresholds.review_floor,
                auto_link: self.thresholds.auto_link,
            });
        }
        if self.weights.is_empty() {
            return Err(ResolutionConfigError::NoWeights);
        }
        Ok(())
    }

    /// Weight for a field, if declared.
    pub fn weight(&self, field: &str) -> Option<FieldWeight> {
        self.weights.get(field).copied()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn starter_path() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../starter/config/resolution.toml")
    }

    #[test]
